diff --git a/apps/birdseye/internal/registry/cache.go b/apps/birdseye/internal/registry/cache.go
index 6513186..8674962 100644
--- a/apps/birdseye/internal/registry/cache.go
+++ b/apps/birdseye/internal/registry/cache.go
@@ -4,6 +4,10 @@
 package registry

 import (
+	"errors"
+	"fmt"
+	"os"
+	"path/filepath"
 	"sync"

 	"github.com/immuta/operations/services/crow/pkg/api"
@@ -47,3 +51,61 @@ func (c *MemCache) Put(m api.Module, body []byte) error {
 	c.items[memKey(m)] = body
 	return nil
 }
+
+// DiskCache stores tarballs under
+//
+//	<root>/<namespace>/<name>/<provider>/<version>.tar.gz
+//
+// Writes are atomic via a temp file + rename.
+type DiskCache struct {
+	root string
+}
+
+// NewDiskCache creates the root directory if it does not exist.
+func NewDiskCache(root string) (*DiskCache, error) {
+	if err := os.MkdirAll(root, 0o755); err != nil {
+		return nil, fmt.Errorf("mkdir cache root: %w", err)
+	}
+	return &DiskCache{root: root}, nil
+}
+
+func (c *DiskCache) path(m api.Module) string {
+	return filepath.Join(c.root, m.Namespace, m.Name, m.Provider, m.Version+".tar.gz")
+}
+
+func (c *DiskCache) Get(m api.Module) ([]byte, bool, error) {
+	b, err := os.ReadFile(c.path(m))
+	if errors.Is(err, os.ErrNotExist) {
+		return nil, false, nil
+	}
+	if err != nil {
+		return nil, false, fmt.Errorf("read cache: %w", err)
+	}
+	return b, true, nil
+}
+
+func (c *DiskCache) Put(m api.Module, body []byte) error {
+	final := c.path(m)
+	if err := os.MkdirAll(filepath.Dir(final), 0o755); err != nil {
+		return fmt.Errorf("mkdir cache dir: %w", err)
+	}
+	tmp, err := os.CreateTemp(filepath.Dir(final), ".birdseye-*.tmp")
+	if err != nil {
+		return fmt.Errorf("create temp: %w", err)
+	}
+	tmpName := tmp.Name()
+	if _, err := tmp.Write(body); err != nil {
+		_ = tmp.Close()
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("write temp: %w", err)
+	}
+	if err := tmp.Close(); err != nil {
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("close temp: %w", err)
+	}
+	if err := os.Rename(tmpName, final); err != nil {
+		_ = os.Remove(tmpName)
+		return fmt.Errorf("rename: %w", err)
+	}
+	return nil
+}
diff --git a/apps/birdseye/internal/registry/cache_test.go b/apps/birdseye/internal/registry/cache_test.go
index 86e2c88..6828506 100644
--- a/apps/birdseye/internal/registry/cache_test.go
+++ b/apps/birdseye/internal/registry/cache_test.go
@@ -29,3 +29,40 @@ func TestMemCacheRoundTrip(t *testing.T) {
 		t.Errorf("body = %q", got)
 	}
 }
+
+func TestDiskCacheMissThenHit(t *testing.T) {
+	dir := t.TempDir()
+	c, err := NewDiskCache(dir)
+	if err != nil {
+		t.Fatalf("NewDiskCache: %v", err)
+	}
+	if _, ok, err := c.Get(mod("1.0.0")); err != nil || ok {
+		t.Fatalf("expected miss; got ok=%v err=%v", ok, err)
+	}
+	if err := c.Put(mod("1.0.0"), []byte("disk-payload")); err != nil {
+		t.Fatalf("Put: %v", err)
+	}
+	got, ok, err := c.Get(mod("1.0.0"))
+	if err != nil || !ok {
+		t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
+	}
+	if string(got) != "disk-payload" {
+		t.Errorf("body = %q", got)
+	}
+}
+
+func TestDiskCacheSurvivesNewInstance(t *testing.T) {
+	dir := t.TempDir()
+	c1, _ := NewDiskCache(dir)
+	if err := c1.Put(mod("2.0.0"), []byte("persisted")); err != nil {
+		t.Fatal(err)
+	}
+	c2, _ := NewDiskCache(dir)
+	got, ok, err := c2.Get(mod("2.0.0"))
+	if err != nil || !ok {
+		t.Fatalf("expected hit; got ok=%v err=%v", ok, err)
+	}
+	if string(got) != "persisted" {
+		t.Errorf("body = %q", got)
+	}
+}
